def get_valid_input(prompt):
    """Get valid input from user until a valid input is provided."""
    while True:
        try:
            user_input = input(prompt)
            return user_input
        except ValueError:
            print("That's not a valid input. Please try again.")

def perform_arithmetic(num1, num2, operation):
    """Perform the given arithmetic operation on two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ZeroDivisionError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operation. Please use +, -, *, /.")
    return result

if __name__ == "__main__":
    num1 = float(input("Enter the first number: "))
    operation = input("Enter the arithmetic operation (+, -, *, /): ")
    num2 = float(input("Enter the second number: "))

    try:
        result = perform_arithmetic(num1, num2, operation)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)
    except ZeroDivisionError as e:
        print(e)
```

This program will keep prompting the user for input until a valid input is provided. It will also handle invalid inputs for the arithmetic operation and division by zero.
